export type ReqStatus = "covered" | "partial" | "missing" | "future";
export type DocStatus = "covered" | "partial" | "missing";

export interface Requirement {
  name: string;
  spec: string;
  status: ReqStatus;
  evidence: string;
  gap: string;
}

export interface DocCoverage {
  docId: string;
  title: string;
  category: string;
  summary: string;
  coveragePercent: number;
  status: DocStatus;
  architectureNotes: string;
  requirements: Requirement[];
  topGaps: string[];
}

